    setState(s => ({ ...s, isAdActive: true, adTimeLeft: 3600, nextBuffAdTime: Date.now() + 3 * 3600000 }));
    alert("📺 광고 시청 완료! 1시간 동안 채굴량이 2배로 증가합니다. (3시간 후 다시 시청 가능)");
  };

  const testPushNotification = async () => {
